def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast local counters
    my_last = 'C'
    opp_last = 'C'
    if n >= 1:
        my_last = history[-1][0]
        opp_last = history[-1][1]

    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    for i in range(n):
        a = history[i][0]
        b = history[i][1]
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'C' and b == 'D':
            cd += 1
        elif a == 'D' and b == 'C':
            dc += 1

    opp_rate = opp_c / float(n)
    my_rate = my_c / float(n)

    # Recent window: last 10
    w = 10
    if n < w:
        w = n
    r_opp_c = 0
    r_my_c = 0
    r_cc = 0
    for i in range(n - w, n):
        a = history[i][0]
        b = history[i][1]
        if b == 'C':
            r_opp_c += 1
        if a == 'C':
            r_my_c += 1
        if a == 'C' and b == 'C':
            r_cc += 1

    # Opponent cooperation streak (backwards)
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    # Opponent defection streak
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    # Opening: always cooperate first, then reciprocal
    if n < 2:
        return 'C'

    # Perfectly cooperative opponent: cooperate, tiny late exploitation
    if opp_c == n:
        if n >= 92 and n <= 97 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Opponent nearly always cooperates: cooperate, punish streak of 3
    if opp_rate >= 0.9:
        if opp_d_streak >= 3:
            return 'D'
        if n >= 92 and n <= 96 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Opponent almost always defects: defect, occasional reset attempt
    if opp_rate <= 0.2:
        if n > 15 and opp_d_streak >= 6 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Highly cooperative overall
    if opp_rate >= 0.7:
        if opp_last == 'D':
            if opp_d_streak >= 2:
                return 'D'
            # forgive single defection often
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        return 'C'

    # Mostly defecting overall
    if opp_rate <= 0.35:
        if opp_last == 'C':
            # they cooperate; reciprocate to encourage
            return 'C'
        if opp_d_streak >= 4 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Middle range: reciprocate with adaptive forgiveness
    if opp_last == 'C':
        # If we've been defecting while they cooperated, resume cooperation
        if my_last == 'D':
            if opp_c_streak >= 3:
                return 'C'
        # occasional probe against very clean recent cooperation
        if r_opp_c == w and n >= 20 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # opp_last == 'D'
    if my_last == 'D':
        # mutual defection; try to break cycle
        if opp_rate >= 0.5 and rng.random() < 0.35:
            return 'C'
        if opp_d_streak >= 5 and opp_rate >= 0.45 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # we cooperated, they defected
    if opp_d_streak >= 3:
        return 'D'
    if opp_rate >= 0.6 and rng.random() < 0.4:
        return 'C'
    return 'D'
